"""Check local documentation links and the generated config/CLI reference."""
import argparse
from dataclasses import fields, MISSING
from pathlib import Path
import re
import sys

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT))
from localagentbridge.config import Config
from localagentbridge.companion_cli import add_parser


def reference():
    lines=['# Configuration and companion CLI reference','',
        'Generated by `python scripts/check_docs.py --write-reference`; checked by the same script.',
        'Run `python -m localagentbridge --config PATH companion ACTION --help` for action flags.',
        'Configuration file selection: explicit `--config`, then `LAB_CONFIG`, then current-directory `config.toml`.',
        'Relative data_dir/source_root/codex_home paths resolve against the selected TOML file.',
        'Existing LAB_MODEL/LAB_ENDPOINT/LAB_DATA_DIR and role overrides remain supported.','',
        '| Top-level key | Default / source |','|---|---|']
    for field in fields(Config):
        value=repr(field.default) if field.default is not MISSING else 'factory: '+getattr(field.default_factory,'__name__','computed')
        lines.append(f'| `{field.name}` | `{value}` |')
    parser=argparse.ArgumentParser()
    commands=parser.add_subparsers(dest='command')
    add_parser(commands)
    companion=commands.choices['companion']
    actions=next(a for a in companion._actions if isinstance(a,argparse._SubParsersAction))
    lines += ['', '## Companion actions', '', '| Action | Flags/arguments |','|---|---|']
    for name,sub in actions.choices.items():
        flags=['/'.join(a.option_strings) or a.dest for a in sub._actions if a.dest!='help']
        lines.append(f'| `{name}` | '+', '.join('`'+f+'`' for f in flags)+' |')
    lines += ['', 'The companion uses `data_dir/companion/companion.sqlite3` (schema 3), with private',
        'callback artifacts under `reviews/<run>/<delivery>/`. No control endpoint is exposed.',
        'The CLI/store interface is the dock contract; state names appear in USER-GUIDE.md.',
        'Existing nested sections: roles, routes, search, delegation, model_registry, adaptive, agentic.',
        'See the existing profiles and workflow guides for those bounded interfaces.',
        'Optional selective.defaults selects a model/backend; selective.model_profiles binds exact identity,',
        'limits and provider controls. selective.project_root restricts that personal profile to one checkout.',
        'Explicit job model overrides the persistent selector, which overrides the configured default.',
        'Profile output/attempt/retry limits may be narrowed; changed context requires separate qualification.',
        'selective.host_limits requires whole-host RAM admission, hard/sustained headroom and GPU ceilings.',
        'See SELECTIVE-SETUP.md for runtime bindings and SELECTIVE-PILOT.md for accounting semantics.',
        'A direct job with no_inference_deadline keeps the HTTP connect timeout at five seconds;',
        'it disables generation/read deadlines, not workflow budgets or callback watchdogs.',
        'Analysis task JSON requires task_key, tool, objective and content. Routed execution',
        'also accepts role/routing/consensus/roles. Tools: analyze_code, summarize_context,',
        'review_diff, analyze_test_output and second_opinion. Workflow submission uses',
        'task_key and the existing typed task instead. See COMPANION-WORKFLOWS.md.',
        'Configured roles select routed execution by default; --model or --execution exact',
        'explicitly selects one exact model. Workflow jobs retain the full v0.5 policy.','']
    return '\n'.join(lines)


def check():
    errors=[]
    count=0
    for path in [*ROOT.glob('*.md'),*(ROOT/'docs').rglob('*.md')]:
        if 'model-evaluations' in path.parts:
            continue
        count+=1
        for target in re.findall(r'!?\[[^\]]*\]\(([^)]+)\)',path.read_text(encoding='utf-8')):
            target=target.strip().strip('<>')
            if re.match(r'\w+://',target) or target.startswith(('#','mailto:')):
                continue
            file=target.split('#')[0]
            if file and not (path.parent/file).exists():
                errors.append(f'{path.relative_to(ROOT)}: missing {file}')
    if (ROOT/'docs/CONFIGURATION.md').read_text(encoding='utf-8')!=reference():
        errors.append('Configuration/CLI reference differs from implemented schema')
    print(f'Checked {count} Markdown files and generated config/CLI reference')
    for error in errors: print(error)
    return int(bool(errors))


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--write-reference',action='store_true')
    args=parser.parse_args()
    if args.write_reference:
        (ROOT/'docs/CONFIGURATION.md').write_text(reference(),encoding='utf-8',newline='\n')
    else:
        raise SystemExit(check())
